  async function apiRequest(path,options={}){const headers={Accept:'application/json',...(options.headers||{})};if(state.apiToken)headers.Authorization=`Bearer ${state.apiToken}`;if(options.body&&!headers['Content-Type'])headers['Content-Type']='application/json';const response=await fetch(`${state.apiBase}${path}`,{...options,headers});let data={};try{data=await response.json();}catch(_){}if(!response.ok)throw new Error(data.error||`Erreur API ${response.status}`);return data;}
  function mapRemoteOrder(o){const items=typeof o.items==='string'?JSON.parse(o.items):o.items;return{id:`TM-${String(o.order_number||'').padStart(4,'0')}`,apiId:o.id,received:new Date(o.created_at).getTime(),customer:o.customer_name,phone:o.customer_phone,mode:o.mode,pay:({pending_verification:'En attente de paiement',paid:'Payé',cash_due:'Espèces à la livraison',not_received:'Non reçu'})[o.payment_status]||o.payment_status,status:o.status,opened:true,items:(items||[]).map(i=>({qty:Number(i.qty)||1,name:i.name,extra:i.extra||'',price:Number(i.unit_price||i.price)||0})),total:Number(o.total)||0,note:o.note||'',prep:o.prep_minutes||null,rejectReason:o.reject_reason||''};}
