  function syncFinanceOrders(){if(!window.TonMenuFinance)return;const s=window.TonMenuFinance.getState(),rows=s.orders.filter(o=>o.restaurantName===state.restaurantName||o.restaurantId==='AYA-01'||o.restaurantId==='aya').map(mapFinanceOrder);orders.splice(0,orders.length,...rows);if(!rows.some(o=>o.id===state.selectedOrder))state.selectedOrder=rows[0]?.id||null;}
  async function loadRemoteBootstrap(){if(!state.apiBase||!state.apiToken)return;state.apiLoading=true;state.apiRequired=true;render();try{const data=await apiRequest('/api/partner/bootstrap');if(!data.restaurant)throw new Error('Aucun établissement lié à ce compte.');orders.splice(0,orders.length,...(data.orders||[]).map(mapRemoteOrder));dishes.splice(0,dishes.length,...(data.dishes||[]).map(d=>({id:d.id,name:d.name,category:d.category,desc:d.description||'',price:Number(d.price),image:d.image||'plats-sauce.webp',available:Boolean(d.available),popular:Boolean(d.popular)})));promos.splice(0,promos.length,...(data.promotions||[]).map(p=>({apiId:p.id,code:p.code,name:p.name,detail:p.detail||'',date:[p.starts_at,p.ends_at].filter(Boolean).join(' — ')||'Dates à définir',usage:'',active:Boolean(p.active)})));reviews.splice(0,reviews.length,...(data.reviews||[]).map(r=>({apiId:r.id,initials:String(r.customer_name||'').split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join(''),customer:r.customer_name,date:new Date(r.created_at).toLocaleDateString('fr-FR'),stars:Number(r.stars),text:r.comment||'',response:r.partner_reply||''})));state.restaurantName=`${data.restaurant.name} — ${data.restaurant.commune}`;const picker=$('#restaurantSelect');if(![...picker.options].some(o=>o.value===state.restaurantName)){const option=document.createElement('option');option.value=state.restaurantName;option.textContent=state.restaurantName;picker.add(option);}picker.value=state.restaurantName;state.status=data.restaurant.is_open?'open':'closed';localStorage.setItem('tmpro-establishment',state.restaurantName);localStorage.setItem('tmpro-status',state.status);state.apiRequired=false;state.apiLoading=false;persist();render();}catch(error){state.apiLoading=false;if(/session|authentification/i.test(error.message)){state.apiToken='';sessionStorage.removeItem('tmpro-api-token');}state.apiRequired=true;render();notify(error.message,'error');}}
  function count(s){return orders.filter(o=>o.status===s).length;}
  function elapsed(ms){const m=Math.max(0,Math.floor(ms/60000));return m<60?`${m} min`:`${Math.floor(m/60)} h ${m%60} min`;}
